"""Generate .env.example from the profile settings classes (single source of truth).

Emits the PROFILE selector plus EVERY profile's full variable block, so a fresh
`.env` works on any supported machine after picking PROFILE.

Run after changing config.py:  just env-example
"""

from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from config import ACTIVE_PROFILE, PROFILES, _PROFILE_CLS

HEADER = """\
# Generated by scripts/gen_env_example.py from config.py -- edit config.py, then regenerate.
# cp .env.example .env   # then set PROFILE; only the active profile's block is read
"""


def default_repr(value) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value)


def main() -> None:
    lines = [HEADER, ""]
    lines += [
        "# --- profile selector -------------------------------------------------",
        "# PROFILE=auto probes torch at startup (GPU present -> strix-halo, else cpu).",
        "# Pin it in .env to skip the probe:",
    ]
    lines += [f"# PROFILE={name}" for name in PROFILES]
    lines.append("PROFILE=auto")
    lines.append("")

    for name in PROFILES:
        cls = _PROFILE_CLS[name]
        prefix: str = cls.model_config.get("env_prefix", "")
        lines.append(f"# === profile: {name}  (env prefix {prefix}*) ===")
        for field_name, field in cls.model_fields.items():
            env_name = f"{prefix}{field_name.upper()}"
            description = (field.description or "").strip()
            default = field.get_default(call_default_factory=True)
            if description:
                lines.append(f"# {description}")
            lines.append(f"{env_name}={default_repr(default)}")
            lines.append("")
        lines.append("")

    out = Path(".env.example")
    out.write_text("\n".join(lines).rstrip() + "\n")
    n = sum(len(cls.model_fields) for cls in _PROFILE_CLS.values())
    print(f"wrote {out} (selector + {len(PROFILES)} profiles, {n} keys; active here: {ACTIVE_PROFILE})")


if __name__ == "__main__":
    main()
